from fastapi import FastAPI, BackgroundTasks
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
from typing import List
import json
import db
import ingest_local
import classify_worker
import github_scout
import github_url_extractor
import pipeline

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["https://x.com", "https://twitter.com", "http://localhost:5174"], 
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.on_event("startup")
def on_startup():
    db.init_db()

@app.get("/api/ideas")
def get_ideas_api(limit: int = 15, offset: int = 0, source: str = 'all', category: str = 'all', intent: str = 'all', search: str = None):
    ideas = db.get_ideas(limit=limit, offset=offset, source=source, category=category, intent=intent, search=search)
    return {
        "ideas": ideas,
        "has_more": len(ideas) == limit,
        "next_offset": offset + limit
    }

@app.patch("/api/ideas/{idea_id}")
def update_idea(idea_id: str, updates: dict):
    try:
        db.update_idea_meta(idea_id, updates)
        return {"status": "success", "message": f"Idea {idea_id} updated."}
    except Exception as e:
        return {"status": "error", "message": str(e)}

